#include <bits/stdc++.h>
using namespace std;

void apply(vector<int>& p, int x, int y) {
    int n = p.size();
    // [0..x-1] [x..n-1-y] [n-y..n-1] -> [n-y..n-1] [x..n-1-y] [0..x-1]
    vector<int> np;
    for (int i = n - y; i < n; i++) np.push_back(p[i]);
    for (int i = x; i < n - y; i++) np.push_back(p[i]);
    for (int i = 0; i < x; i++) np.push_back(p[i]);
    p = np;
}

int main(){
    int n;
    scanf("%d", &n);
    vector<int> p(n);
    for (int i = 0; i < n; i++) scanf("%d", &p[i]);

    vector<pair<int,int>> ops;

    for (int placed = 0; placed < n - 2; placed++) {
        // Find where (placed+1) is
        int pos = -1;
        for (int i = placed; i < n; i++) if (p[i] == placed + 1) { pos = i; break; }
        if (pos == placed) continue;

        // Step 1: Move element to position n-1 if not already there
        if (pos != n - 1) {
            // x = pos+1, y = n-1-pos. But x+y = pos+1+n-1-pos = n, need < n.
            // So use x = pos+1, y = n-1-pos-1 = n-2-pos (if > 0, i.e., pos < n-2)
            // This puts element at position y (since it was last of prefix, now last of whole)
            // Actually: prefix=[0..pos], middle=[pos+1..pos+1+?], suffix=[n-y-1..n-1]
            // Element at pos (end of prefix) goes to end of new array (position n-1)... 
            // Wait: new = [suffix | middle | prefix]. Element at pos is last of prefix -> last of array = position n-1. 
            // But we need middle to be non-empty: x + y < n => pos+1 + (n-1-pos) = n, not < n.
            // Use y = n - 2 - pos (one less). Then x + y = pos + 1 + n - 2 - pos = n - 1 < n. Good if y > 0 => pos < n-2.
            if (pos < n - 2) {
                int x = pos + 1, y = n - 2 - pos;
                ops.push_back({x, y});
                apply(p, x, y);
                // element was at end of prefix (index pos = x-1), goes to position n-1
                // Verify:
                pos = n - 1;
            } else {
                // pos == n-2: element is at n-2. Use x=1, y=1 to cycle, then retry.
                // [p[0]] [p[1]..p[n-2]] [p[n-1]] -> [p[n-1]] [p[1]..p[n-2]] [p[0]]
                ops.push_back({1, 1});
                apply(p, 1, 1);
                // Now find element again
                for (int i = placed; i < n; i++) if (p[i] == placed + 1) { pos = i; break; }
                if (pos == placed) continue;
                if (pos != n - 1 && pos < n - 2) {
                    int x = pos + 1, y = n - 2 - pos;
                    ops.push_back({x, y});
                    apply(p, x, y);
                    pos = n - 1;
                } else if (pos == n - 1) { /* good */ }
                else continue;
            }
        }
        if (pos != n - 1 || p[pos] != placed + 1) continue;

        // Step 2: Move element from position n-1 to position 'placed'
        // x = placed, y = 1: new = [p[n-1]] [p[placed]..p[n-2]] [p[0]..p[placed-1]]
        // Element goes to position 0. We want position 'placed'. 
        // Use x = n-1-placed, y = 1. Nope. Let's think: we want suffix (y=1, element at n-1) to go to front.
        // Then prefix of size x goes to back. Element lands at position 0.
        // For it to land at position 'placed': y = 1, x = n-1-placed. Check: x+y = n-placed < n (if placed>0).
        if (placed > 0) {
            int x = n - 1 - placed, y = 1;
            ops.push_back({x, y});
            apply(p, x, y);
        } else {
            // placed=0: want element at pos n-1 to go to pos 0. x+y<n, y=1, x=n-1: x+y=n not <n.
            // x=n-2, y=1: element at n-1 goes to pos 0. prefix [0..n-3] goes to end. 
            int x = n - 2, y = 1;
            ops.push_back({x, y});
            apply(p, x, y);
        }
    }

    printf("%d\n", (int)ops.size());
    for (auto& [x, y] : ops) printf("%d %d\n", x, y);
}
